def rd(title, key):
    return {"title": title, "url": DOCS[key]}

def q(prompt, a, b, c, d, correct, explanation):
    """Build a question dict. correct = 'A'|'B'|'C'|'D'"""
    choices = [
        {"option": "A", "text": a},
        {"option": "B", "text": b},
        {"option": "C", "text": c},
        {"option": "D", "text": d},
    ]
    correct_text = {"A": a, "B": b, "C": c, "D": d}[correct]
    return {
        "prompt": prompt,
        "choices": choices,
        "correct_option": correct,
        "correct_text": correct_text,
        "explanation": explanation,
    }

