# ══════════════════════════════════════════════════════════════════════════════
# Helper: build a standard 8-week set for programs with similar patterns
# ══════════════════════════════════════════════════════════════════════════════

def make_weeks_for_program(program_slug, week_defs):
    """week_defs: list of (week_title, focus, required_reading_list, key_terms_list, questions_list)"""
    weeks = []
    for i, (title, focus, reading, terms, questions) in enumerate(week_defs):
        weeks.append({
            "week_number": i + 1,
            "week_title": title,
            "focus": focus,
            "passing_score": 70,
            "study_prompt": "Review all assigned documents for this week before attempting the quiz.",
            "required_reading": reading,
            "key_terms": terms,
            "quiz_questions": questions,
            "discussion_questions": [
                {"prompt": f"How does the lesson of {title} apply to your conduct, service, and accountability within the Order?",
                 "purpose": "Move from summary knowledge to lived application."},
                {"prompt": f"Which document or reading from {title} most shaped your understanding, and why?",
                 "purpose": "Require evidence-based discussion grounded in assigned materials."},
                {"prompt": f"What previous program material should be reviewed alongside {title}, and how does it strengthen your readiness?",
                 "purpose": "Encourage cumulative review and progression."},
            ],
        })
    return weeks

