KNIGHT_WEEKS = []
for i, d in enumerate(KNIGHT_WEEKS_DEF):
    title, focus, reading, terms, questions = d
    KNIGHT_WEEKS.append({
        "week_number": i+1, "week_title": title, "focus": focus,
        "passing_score": 70,
        "study_prompt": "Review all assigned documents before the quiz.",
        "required_reading": reading,
        "key_terms": terms,
        "quiz_questions": questions,
        "discussion_questions": [
            "How does this week's focus challenge your current understanding of leadership?",
            "Where do you see this principle tested in your own chapter context?",
            "What would it look like to fully embody this week's standard in daily life?"
        ],
    })
print("Knight weeks built:", len(KNIGHT_WEEKS))

