import json as _json, os as _os

_JSON_PATH = "src/config/curriculum/full-program-curriculum.json"
with open(_JSON_PATH) as _f:
    _data = _json.load(_f)

_SLUG_TO_WEEKS = {
    "levie":           LEVIE_WEEKS,
    "squire":          SQUIRE_WEEKS,
    "corporal":        CORPORAL_WEEKS,
    "sergeant":        SERGEANT_WEEKS,
    "sfc":             SFC_WEEKS,
    "knight-aspirant": KA_WEEKS,
    "knight":          KNIGHT_WEEKS,
    "lieutenant":      LT_WEEKS,
    "captain":         CAPTAIN_WEEKS,
    "major":           MAJOR_WEEKS,
    "commander":       COMMANDER_WEEKS,
}

for _prog in _data["programs"]:
    _slug = _prog["slug"]
    if _slug in _SLUG_TO_WEEKS:
        _prog["weeks"] = _SLUG_TO_WEEKS[_slug]
        # Ensure every week carries passing_score
        for _wk in _prog["weeks"]:
            _wk.setdefault("passing_score", 70)
        print(f"Patched {_slug}: {len(_prog['weeks'])} weeks")

with open(_JSON_PATH, "w") as _f:
    _json.dump(_data, _f, indent=2)
